-- HIT A 64유형 강점·주의점·잘 맞는 방향 문장화 (2026-10-13 적용)
-- 결함: 주의점 192개 중 128개가 14자 미만 조각('슈퍼비전 정기'), 방향 64개가 'A → B → C 방향.' 전보문. 대학생·사회 초년 대상 문장으로 재작성.
-- 원문(JSON): sql/hit-hero-types-copy-2026-10/{D,I,S,C}.json — 이 파일은 그 JSON에서 생성. 화면: features/hit/HitAResultView.tsx '강점·주의점' 섹션
-- 롤백: 이전 값은 Supabase PITR 없음(Free) → 적용 전 스냅샷을 hit_hero_types_backup_20261013 테이블로 보존
CREATE TABLE IF NOT EXISTS public.hit_hero_types_backup_20261013 AS SELECT type_code, strengths, cautions, fit_direction FROM public.hit_hero_types;
ALTER TABLE public.hit_hero_types_backup_20261013 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.hit_hero_types_backup_20261013 FROM anon, authenticated;
GRANT ALL ON public.hit_hero_types_backup_20261013 TO service_role;

UPDATE public.hit_hero_types SET strengths = '["사람의 장단점을 깊이 읽고 정확하게 짚어 줍니다.", "칭찬보다 성장에 도움이 되는 솔직한 피드백을 줍니다.", "높은 기준과 진심 어린 관심을 함께 보여 줍니다.", "답을 대신 주기보다 질문으로 상대가 스스로 답을 찾게 합니다."]'::jsonb, cautions = '["기준이 높아 상대가 위축될 수 있어요. 피드백의 목적이 성장이라는 걸 먼저 말해 주세요.", "고칠 점을 말할 때 잘한 점도 함께 짚어 주면 더 잘 받아들여집니다.", "모든 사람에게 같은 기준을 적용하기보다 상대의 단계에 맞춰 조절해 보세요."]'::jsonb, fit_direction = '지금은 스터디 리더·멘토링·면접 스터디처럼 다른 사람의 성장을 돕고 피드백하는 경험을 쌓아 보세요. 첫 직무로는 HR·채용·인재 평가·교육 기획이 잘 맞습니다. 길게는 사람을 정확히 보고 키우는 리더십 코치나 인재 전문가로 성장할 수 있습니다.' WHERE type_code = 'C-ENFJ';
UPDATE public.hit_hero_types SET strengths = '["관심 분야가 넓지만 한 주제에 빠지면 끝까지 파고듭니다.", "결과물의 완성도를 높이려는 기준이 있습니다.", "여러 자료를 연결해 새로운 통찰을 만들어 냅니다.", "새로운 것을 탐색하는 에너지가 넘칩니다."]'::jsonb, cautions = '["완벽하게 하려다 마무리가 늦어질 수 있어요. 마감을 잘 지키는 동료와 함께 일해 보세요.", "탐구 범위가 끝없이 넓어지지 않도록 시작할 때 범위를 정해 두세요.", "완성되기 전에도 중간 결과를 보여 주고 의견을 받아 보세요."]'::jsonb, fit_direction = '지금은 트렌드 리포트·리서치 프로젝트·공모전 기획서로 조사와 분석 경험을 쌓아 보세요. 첫 직무로는 리서치·트렌드 분석·마케팅 인사이트·연구 기획이 잘 맞습니다. 길게는 통찰을 이끄는 리서치 리더나 컨설턴트로 성장할 수 있습니다.' WHERE type_code = 'C-ENFP';
UPDATE public.hit_hero_types SET strengths = '["감이 아니라 숫자와 근거로 결정합니다.", "데이터를 바탕으로 장기 전략을 정밀하게 세웁니다.", "성과를 숫자로 설명해 사람들을 설득합니다.", "숫자와 사업의 흐름을 연결해 큰 그림을 봅니다."]'::jsonb, cautions = '["숫자에 드러나지 않는 요인을 놓칠 수 있어요. 현장과 고객을 직접 만나 보세요.", "데이터만으로 설득이 안 될 때는 사람들의 마음도 함께 살펴보세요.", "분석과 감각이 다를 때는 둘 다 기록해 두고 결과로 비교해 보세요."]'::jsonb, fit_direction = '지금은 경영 사례 분석 대회·투자 동아리·재무 분석 프로젝트로 숫자 기반 판단을 연습해 보세요. 첫 직무로는 경영 컨설팅·재무 기획·전략 기획·투자 분석이 잘 맞습니다. 길게는 숫자로 회사의 방향을 정하는 전략 총괄이나 재무 임원으로 성장할 수 있습니다.' WHERE type_code = 'C-ENTJ';
UPDATE public.hit_hero_types SET strengths = '["시스템의 약점을 남들보다 먼저 발견합니다.", "논리를 정교하게 따져 허점을 짚어 냅니다.", "위험이 커지기 전에 미리 알아챕니다.", "문제를 지적하는 데서 그치지 않고 대안을 내놓을 수 있습니다."]'::jsonb, cautions = '["비판만 남기면 팀이 지칠 수 있어요. 문제를 짚을 때는 대안 하나를 꼭 함께 내세요.", "반대 의견을 낼 때 상대의 노력도 함께 인정하면 대화가 잘 풀립니다.", "실행을 맡아 줄 사람과 짝을 이루면 지적이 개선으로 이어집니다."]'::jsonb, fit_direction = '지금은 서비스 버그 찾기·모의 감사·토론 대회처럼 허점을 찾고 개선안을 내는 경험을 해 보세요. 첫 직무로는 품질 보증(QA)·보안·감사·리스크 관리가 잘 맞습니다. 길게는 조직의 위험을 지키는 리스크 책임자나 보안·감사 전문가로 성장할 수 있습니다.' WHERE type_code = 'C-ENTP';
UPDATE public.hit_hero_types SET strengths = '["품질 기준과 사람에 대한 배려를 함께 지킵니다.", "결과물의 품질을 꼼꼼하게 관리하는 감각이 있습니다.", "모두가 따를 수 있는 서비스 기준을 설계합니다.", "기준을 알릴 때도 따뜻한 말로 전달합니다."]'::jsonb, cautions = '["기준이 너무 많아지면 팀이 느려질 수 있어요. 꼭 지킬 것과 권장할 것을 나눠 두세요.", "팀의 속도를 고려해 기준을 한 번에 다 적용하지 말고 단계적으로 도입하세요.", "기준을 지키지 못한 사람을 탓하기보다 왜 어려웠는지 먼저 물어보세요."]'::jsonb, fit_direction = '지금은 행사 매뉴얼 만들기·신입 교육 자료 제작처럼 기준을 정리하는 경험을 쌓아 보세요. 첫 직무로는 품질 관리·교육 기획·서비스 운영·CS 기획이 잘 맞습니다. 길게는 품질과 교육을 책임지는 디렉터나 컨설턴트로 성장할 수 있습니다.' WHERE type_code = 'C-ESFJ';
UPDATE public.hit_hero_types SET strengths = '["관객이 눈치채지 못하는 작은 장치까지 챙깁니다.", "분위기와 감동을 섬세하게 연출하는 감각이 있습니다.", "현장을 지휘하며 계획을 정확하게 실현합니다.", "완성도와 재미를 함께 만들어 냅니다."]'::jsonb, cautions = '["디테일 욕심이 지나치면 지칠 수 있어요. 꼭 챙길 것과 넘어가도 될 것을 미리 나눠 두세요.", "바쁜 시기가 끝나면 반드시 쉬는 시간을 가지세요.", "팀과 완성도 기준을 미리 맞춰 두면 마지막 순간의 갈등이 줄어듭니다."]'::jsonb, fit_direction = '지금은 공연·축제·행사 기획단에서 연출과 진행을 맡아 보세요. 첫 직무로는 방송·영상 PD·이벤트 기획·공연 기획·전시 기획이 잘 맞습니다. 길게는 기획과 연출을 총괄하는 디렉터로 성장할 수 있습니다.' WHERE type_code = 'C-ESFP';
UPDATE public.hit_hero_types SET strengths = '["조직의 규칙이 제대로 지켜지도록 관리합니다.", "기준에 따라 공정하게 판단합니다.", "위험이 생기기 전에 절차로 예방합니다.", "책임감이 강해 맡은 영역을 끝까지 지킵니다."]'::jsonb, cautions = '["규칙의 목적은 잊고 형식만 지키게 될 수 있어요. 가끔 ''이 규칙은 왜 있지?''를 다시 물어보세요.", "엄격함만큼 상대가 이해할 수 있게 설명하는 것도 중요합니다.", "바뀐 환경에 맞지 않는 규칙은 고치자고 먼저 제안해 보세요."]'::jsonb, fit_direction = '지금은 학생회 감사·예산 검토·규정 정리처럼 기준을 지키는 역할을 맡아 보세요. 첫 직무로는 내부 감사·컴플라이언스·법무 지원·공공기관이 잘 맞습니다. 길게는 조직의 기준을 책임지는 감사·리스크 임원으로 성장할 수 있습니다.' WHERE type_code = 'C-ESTJ';
UPDATE public.hit_hero_types SET strengths = '["압박 속에서도 정확하게 판단하고 움직입니다.", "즉흥적이지 않고 훈련된 정밀함으로 실행합니다.", "실전에서 기술과 판단을 동시에 발휘합니다.", "반복 훈련으로 실력을 꾸준히 끌어올립니다."]'::jsonb, cautions = '["압박이 오래 이어지면 판단이 굳어질 수 있어요. 회복과 훈련을 루틴으로 관리하세요.", "실수를 줄이려면 체크리스트를 만들어 매번 확인해 보세요.", "혼자 해결하려 하기보다 팀과 상황을 공유하며 판단해 보세요."]'::jsonb, fit_direction = '지금은 실습·대회·자격증처럼 정확한 기술을 반복해서 익히는 경험을 쌓아 보세요. 첫 직무로는 의료·항공·스포츠 심판·특수 기술직처럼 정밀함이 필요한 분야가 잘 맞습니다. 길게는 그 분야의 마스터나 실전 교육 전문가로 성장할 수 있습니다.' WHERE type_code = 'C-ESTP';
UPDATE public.hit_hero_types SET strengths = '["사람과 조직의 말하지 않은 생각까지 읽어 냅니다.", "깊이 관찰해 문화와 행동의 숨은 이유를 찾습니다.", "이야기 속에서 의미를 해석하는 힘이 있습니다.", "복잡한 사람의 마음을 체계적으로 정리합니다."]'::jsonb, cautions = '["해석이 깊어질수록 실행과 멀어질 수 있어요. 분석이 실제 정책이나 제품에 어떻게 쓰일지 함께 정리하세요.", "혼자 깊이 생각하기보다 동료와 해석을 나누며 검증해 보세요.", "결론을 미루지 않도록 연구마다 마감을 정해 두세요."]'::jsonb, fit_direction = '지금은 인터뷰 조사·관찰 연구·사회 문제 리서치로 사람을 깊이 이해하는 경험을 쌓아 보세요. 첫 직무로는 사용자 리서치(UX 리서치)·사회 연구·조직문화·HR 분석이 잘 맞습니다. 길게는 사람과 조직을 해석하는 리서치 리더나 자문가로 성장할 수 있습니다.' WHERE type_code = 'C-INFJ';
UPDATE public.hit_hero_types SET strengths = '["작은 부분까지 옳은지 따지며 가치를 지킵니다.", "윤리와 공정함을 중요하게 여기고 기준을 세웁니다.", "디테일한 부분에서 놓친 불공정을 찾아냅니다.", "자신이 믿는 원칙을 꾸준히 지켜 갑니다."]'::jsonb, cautions = '["타협이 필요한 순간에 받아들이기 어려울 수 있어요. 꼭 지킬 가치와 바꿔도 되는 방법을 구분해 보세요.", "완벽한 공정함을 기다리기보다 지금 할 수 있는 개선부터 시작해 보세요.", "생각이 다른 사람과도 대화를 이어 가면 가치가 더 멀리 퍼집니다."]'::jsonb, fit_direction = '지금은 인권·환경·공정 관련 동아리나 연구 프로젝트에 참여해 보세요. 첫 직무로는 ESG·윤리 경영·공공 정책·비영리 기관이 잘 맞습니다. 길게는 가치를 지키는 기관의 전문가나 책임자로 성장할 수 있습니다.' WHERE type_code = 'C-INFP';
UPDATE public.hit_hero_types SET strengths = '["실행하기 전에 머릿속에서 전체를 철저히 설계합니다.", "복잡한 문제를 구조화해 빈틈없는 계획을 세웁니다.", "위험 요소를 미리 계산해 대비합니다.", "수준 높은 기준으로 체계를 만듭니다."]'::jsonb, cautions = '["설계가 완벽해질 때까지 시작을 미룰 수 있어요. 작은 단위로 먼저 시험해 보세요.", "계획을 혼자 완성하지 말고 중간에 동료와 검토해 보세요.", "예상과 다른 결과가 나오면 계획을 고치는 것도 설계의 일부입니다."]'::jsonb, fit_direction = '지금은 시스템 설계·알고리즘 문제 풀이·전략 공모전으로 구조를 짜는 경험을 쌓아 보세요. 첫 직무로는 시스템 설계·보안·전략 기획·데이터 아키텍처가 잘 맞습니다. 길게는 복잡한 시스템을 책임지는 아키텍트나 전략 총괄로 성장할 수 있습니다.' WHERE type_code = 'C-INTJ';
UPDATE public.hit_hero_types SET strengths = '["근거가 빈틈없이 이어져야 결론을 냅니다.", "복잡한 문제를 논리적으로 끝까지 풉니다.", "한 번 검증한 결론은 쉽게 흔들리지 않습니다.", "추상적인 이론을 깊이 이해합니다."]'::jsonb, cautions = '["혼자 쌓은 분석은 전달되지 않으면 쓰이지 못해요. 중간 결과를 정기적으로 공유하세요.", "어려운 내용을 쉬운 말로 설명하는 연습을 해 보세요.", "완벽한 증명을 기다리기보다 지금 결론의 확신 정도를 함께 밝혀 보세요."]'::jsonb, fit_direction = '지금은 수학·알고리즘 대회·이론 연구 세미나로 논리를 깊이 다루는 경험을 쌓아 보세요. 첫 직무로는 연구원·알고리즘 개발·데이터 사이언스·퀀트 분석이 잘 맞습니다. 길게는 그 분야를 대표하는 연구자나 기술 전문가로 성장할 수 있습니다.' WHERE type_code = 'C-INTP';
UPDATE public.hit_hero_types SET strengths = '["꼼꼼한 기록과 관찰로 사람을 세심하게 돕습니다.", "정해진 절차를 정확히 지켜 안전을 챙깁니다.", "작은 변화도 놓치지 않고 알아챕니다.", "오래 곁에 있으며 신뢰를 쌓습니다."]'::jsonb, cautions = '["절차를 지키다 예외 상황에서 굳어질 수 있어요. 무엇이 가장 중요한지 우선순위를 먼저 판단해 보세요.", "혼자 꼼꼼히 챙기느라 지치지 않도록 동료와 일을 나눠 보세요.", "내가 관찰한 것을 적극적으로 공유하면 팀 전체가 도움을 받습니다."]'::jsonb, fit_direction = '지금은 교육 봉사·실습·기록 관리처럼 정확함과 배려가 함께 필요한 경험을 쌓아 보세요. 첫 직무로는 의료 보건·재활·교육·의무 기록 관리가 잘 맞습니다. 길게는 그 분야의 전문가나 후배를 지도하는 책임자로 성장할 수 있습니다.' WHERE type_code = 'C-ISFJ';
UPDATE public.hit_hero_types SET strengths = '["정확한 손길과 섬세한 감수성을 함께 가지고 있습니다.", "작은 디테일까지 공들여 완성도를 높입니다.", "자기만의 감각으로 결과물에 개성을 담습니다.", "꾸준한 연습으로 기술을 정교하게 다듬습니다."]'::jsonb, cautions = '["완벽주의 때문에 결과물을 내놓지 못할 수 있어요. 초안이나 중간 작업을 먼저 공개해 보세요.", "작업 시간을 정해 두면 몰입과 휴식의 균형을 지킬 수 있습니다.", "의뢰인의 요청과 내 감각이 다를 때는 먼저 질문해서 기대를 맞춰 보세요."]'::jsonb, fit_direction = '지금은 일러스트·공예·디자인 작업을 꾸준히 만들어 포트폴리오로 쌓아 보세요. 첫 직무로는 일러스트레이터·제품 디자인·공예 디자인·복원 분야가 잘 맞습니다. 길게는 아트 디렉터나 자기 스튜디오를 운영하는 창작자로 성장할 수 있습니다.' WHERE type_code = 'C-ISFP';
UPDATE public.hit_hero_types SET strengths = '["정해진 기준과 절차를 정확히 지켜 실수가 거의 없습니다.", "한 번 맡은 일은 끝까지 책임지고 마무리합니다.", "시간이 쌓일수록 \"이 사람에게 맡기면 된다\"는 신뢰가 커집니다.", "한 분야를 깊이 파고들어 전문성을 단단하게 쌓습니다."]'::jsonb, cautions = '["완벽하게 하려다 마감을 놓칠 수 있어요. 시작할 때 \"어디까지 하면 완료인지\"를 먼저 정하세요.", "정확성과 속도 중 지금 무엇이 중요한지 상황마다 확인해 보세요.", "익숙한 방식이 편하더라도 분기마다 새 도구나 방법 하나를 시도해 보세요."]'::jsonb, fit_direction = '지금은 자격증 준비나 데이터 정리처럼 정확성이 필요한 경험을 쌓아 보세요. 첫 직무로는 회계·재무·법무·품질관리·운영이 잘 맞습니다. 길게는 그 분야에서 믿고 맡기는 전문가나 자문가로 성장할 수 있습니다.' WHERE type_code = 'C-ISTJ';
UPDATE public.hit_hero_types SET strengths = '["겉으로 드러난 증상이 아니라 근본 원인을 찾아냅니다.", "꼼꼼한 관찰로 문제의 흐름을 추적합니다.", "도구를 능숙하게 다뤄 정확하게 진단합니다.", "복잡한 문제 앞에서도 침착하게 원인을 좁혀 갑니다."]'::jsonb, cautions = '["혼자 해결하려다 협업이 늦어질 수 있어요. 중요한 발견은 짧게라도 바로 공유하세요.", "해결한 과정을 기록해 두면 같은 문제가 생겼을 때 모두가 빨라집니다.", "원인을 찾는 데만 집중하지 말고 재발을 막을 방법도 함께 제안해 보세요."]'::jsonb, fit_direction = '지금은 디버깅·고장 진단·보안 대회(CTF)처럼 원인을 찾는 문제를 풀어 보세요. 첫 직무로는 개발자·시스템 엔지니어·보안 분석·품질 분석이 잘 맞습니다. 길게는 어려운 문제를 진단하는 분석 전문가나 기술 마스터로 성장할 수 있습니다.' WHERE type_code = 'C-ISTP';
UPDATE public.hit_hero_types SET strengths = '["흩어진 사람들의 고민을 하나의 목표로 묶어 모두가 같은 방향을 보게 만듭니다.", "진심이 담긴 말로 설득해, 사람들이 스스로 함께하고 싶게 만듭니다.", "방향을 제시하는 데서 끝나지 않고 실행까지 앞장서 챙깁니다.", "팀이 흔들릴 때 중심을 잡아 주는 든든한 무게감이 있습니다."]'::jsonb, cautions = '["반대 의견이 나오면 ''저항''이 아니라 놓친 부분을 알려 주는 신호로 들어 보세요.", "사명감이 클수록 쉽게 지칩니다. 바쁜 시기가 오기 전에 쉬는 날을 먼저 정해 두세요.", "내 속도로 팀을 끌고 가기 전에, 팀이 따라올 수 있는 속도인지 한 번씩 확인하세요."]'::jsonb, fit_direction = '지금은 동아리·학회·봉사 단체에서 사람을 모아 무언가를 함께 이뤄 보는 경험을 쌓아 보세요. 첫 직무로는 HR·조직문화·교육 기획·사회공헌·PM처럼 사람과 목표를 함께 다루는 일이 잘 맞습니다. 길게는 조직이나 공동체를 이끄는 리더, 의미 있는 일을 하는 단체·기업의 창립자로 성장할 수 있습니다.' WHERE type_code = 'D-ENFJ';
UPDATE public.hit_hero_types SET strengths = '["아무도 시작하지 않은 일에 먼저 뛰어들어 첫 흐름을 만들어 냅니다.", "이야기를 풀어내는 힘이 있어 사람들이 자연스럽게 내 아이디어에 모입니다.", "''안 될 것 같다''는 말을 들으면 오히려 방법을 찾고 싶어집니다.", "생각을 빠르게 시제품이나 시범 운영으로 옮겨 반응을 확인합니다."]'::jsonb, cautions = '["시작은 뜨겁지만 반복되는 운영은 지루해질 수 있어요. 꾸준히 굴려 줄 파트너를 일찍 찾아 두세요.", "아이디어가 너무 많으면 아무것도 끝나지 않습니다. 매주 이번 주에 할 한 가지만 골라 보세요.", "초기 반응에 일희일비하지 않도록, 길게 보고 조언해 줄 멘토를 곁에 두세요."]'::jsonb, fit_direction = '지금은 창업 동아리·공모전·사이드 프로젝트로 아이디어를 실제로 세상에 내놓는 경험을 해 보세요. 첫 직무로는 신사업 기획·브랜드 마케팅·스타트업 초기 멤버·캠페인 기획이 잘 맞습니다. 길게는 새로운 시장을 여는 창업가나 혁신 프로젝트를 이끄는 리더로 성장할 수 있습니다.' WHERE type_code = 'D-ENFP';
UPDATE public.hit_hero_types SET strengths = '["복잡한 상황을 한두 줄의 전략으로 정리해 모두가 같은 방향을 보게 만듭니다.", "먼 목표와 이번 주 할 일을 연결해, 계획이 실행으로 이어지게 합니다.", "결정해야 할 순간에 망설이지 않고 책임지고 정합니다.", "기준이 높아 함께 일하는 사람의 수준까지 끌어올립니다."]'::jsonb, cautions = '["효율에 집중하다 팀의 기분을 놓칠 수 있어요. 회의 끝에 \"다들 괜찮아?\"를 한 번 물어보세요.", "결정 전에 반대 의견을 일부러 한 번 더 들어 보세요. 놓친 위험이 거기서 보입니다.", "모든 걸 직접 쥐려 하지 말고 맡길 일은 맡겨 보세요. 위임도 리더의 기술입니다."]'::jsonb, fit_direction = '지금은 학회·공모전·팀 프로젝트에서 리더를 맡아 사람과 일정을 함께 관리해 보세요. 첫 직무로는 전략기획·사업개발·PM·컨설팅이 잘 맞습니다. 길게는 조직을 이끄는 경영자나 창업가로 성장할 수 있습니다.' WHERE type_code = 'D-ENTJ';
UPDATE public.hit_hero_types SET strengths = '["익숙한 방식에서 남들이 놓친 허점을 바로 찾아냅니다.", "기존 방식을 뜯어보고 더 나은 방식으로 다시 짜는 설계 감각이 있습니다.", "논쟁을 피하지 않고, 부딪히는 의견에서 새로운 답을 끌어냅니다.", "아직 아무도 주목하지 않은 기회를 먼저 알아봅니다."]'::jsonb, cautions = '["바꾸자고 하는 것보다 바꾼 뒤를 굴리는 게 더 어렵습니다. 시작할 때 이후 몇 달의 계획도 함께 세우세요.", "문제를 지적할 때는 대안도 한 가지 함께 내놓아 보세요. 비판이 제안이 됩니다.", "아이디어만 던지고 빠지지 않도록, 끝까지 실행해 줄 파트너와 짝을 이루세요."]'::jsonb, fit_direction = '지금은 공모전·해커톤·비즈니스 케이스 대회에서 기존 방식을 새롭게 바꾸는 제안을 해 보세요. 첫 직무로는 서비스 기획·전략 컨설팅·사업개발·제품 관리(PM)가 잘 맞습니다. 길게는 시장의 판을 바꾸는 창업가나 혁신 조직의 리더로 성장할 수 있습니다.' WHERE type_code = 'D-ENTP';
UPDATE public.hit_hero_types SET strengths = '["성과 목표와 팀 분위기를 함께 챙겨, 숫자도 사람도 놓치지 않습니다.", "팀이 지치지 않고 끝까지 가도록 분위기를 책임집니다.", "여러 부서나 사람 사이에서 일정을 맞추고 협업을 매끄럽게 조율합니다.", "누구에게 어떤 말이 힘이 되는지 알아채고 동기를 북돋웁니다."]'::jsonb, cautions = '["모두를 챙기다 내가 먼저 지칠 수 있어요. 맡길 수 있는 일은 과감히 나눠 맡기세요.", "에너지가 바닥나기 전에 회복 시간을 일정에 먼저 넣어 두세요.", "성과와 관계 중 한쪽으로 치우치지 않았는지 한 달에 한 번 돌아보세요."]'::jsonb, fit_direction = '지금은 동아리·행사 운영진을 맡아 목표를 정하고 사람들을 이끌어 끝까지 해내는 경험을 쌓아 보세요. 첫 직무로는 영업 관리·고객 관리·HR·운영 매니저가 잘 맞습니다. 길게는 사람과 성과를 함께 책임지는 조직 리더로 성장할 수 있습니다.' WHERE type_code = 'D-ESFJ';
UPDATE public.hit_hero_types SET strengths = '["현장의 열기를 끌어올려 실제 결과로 바꿔 냅니다.", "위기가 오면 누구보다 먼저 몸을 움직여 해결에 나섭니다.", "가라앉은 분위기에 생기를 불어넣는 존재감이 있습니다.", "상황을 보자마자 판단하고 바로 실행에 옮깁니다."]'::jsonb, cautions = '["기분이 성과에 그대로 드러날 수 있어요. 컨디션이 좋은 때와 처지는 때를 기록해 패턴을 알아 두세요.", "눈앞의 일에 집중하다 먼 계획을 놓치기 쉽습니다. 한 달에 한 번은 앞으로의 계획을 점검하세요.", "감정이 크게 움직일 때는 중요한 결정을 하루 미뤄 보세요."]'::jsonb, fit_direction = '지금은 행사 운영·판매·홍보처럼 사람을 직접 만나는 현장 경험을 쌓아 보세요. 첫 직무로는 영업·이벤트 기획·매장 운영·브랜드 현장 마케팅이 잘 맞습니다. 길게는 현장을 이끄는 총괄 매니저나 자기 브랜드를 운영하는 창업가로 성장할 수 있습니다.' WHERE type_code = 'D-ESFP';
UPDATE public.hit_hero_types SET strengths = '["어수선한 상황에 체계를 세워 일이 제대로 굴러가게 만듭니다.", "목표·일정·역할을 분명히 나눠 팀이 헷갈리지 않게 합니다.", "규모가 큰 일도 흔들림 없이 안정적으로 운영합니다.", "맡은 일에 대한 책임감이 깊어 끝까지 해냅니다."]'::jsonb, cautions = '["계획대로 되지 않는 상황에 대비해 ''이렇게 안 되면''을 한 가지씩 미리 준비해 두세요.", "변화가 필요한 순간에는 익숙한 방식을 잠시 내려놓는 연습을 해 보세요.", "팀원이 스스로 방법을 정할 여지를 남겨 두면 팀이 더 오래 갑니다."]'::jsonb, fit_direction = '지금은 행사·프로젝트의 운영 총괄을 맡아 일정과 사람을 체계적으로 관리해 보세요. 첫 직무로는 운영 관리·생산 관리·물류·프로젝트 관리(PMO)가 잘 맞습니다. 길게는 큰 조직의 운영을 책임지는 총괄 리더로 성장할 수 있습니다.' WHERE type_code = 'D-ESTJ';
UPDATE public.hit_hero_types SET strengths = '["예상하지 못한 상황에서 오히려 빠르고 정확하게 판단합니다.", "망설이는 대신 과감하게 움직여 막힌 문제를 뚫습니다.", "직접 부딪혀 본 경험에서 나온 실전 감각이 있습니다.", "위기를 기회로 바꾸는 순발력이 있습니다."]'::jsonb, cautions = '["긴 계획을 세우는 일은 지루해질 수 있어요. 큰 그림을 함께 볼 동료와 역할을 나눠 보세요.", "반복 업무가 많은 자리에서는 금방 지칠 수 있습니다. 내가 움직일 수 있는 역할을 찾아 두세요.", "바쁘게 달리다 갑자기 지치지 않도록 쉬는 시간을 미리 정해 두세요."]'::jsonb, fit_direction = '지금은 판매·현장 아르바이트·대회처럼 직접 부딪혀 결과를 내는 경험을 쌓아 보세요. 첫 직무로는 영업·현장 운영·위기 대응·스포츠·이벤트 분야가 잘 맞습니다. 길게는 실전에서 판을 이끄는 리더나 특정 분야의 해결사로 성장할 수 있습니다.' WHERE type_code = 'D-ESTP';
UPDATE public.hit_hero_types SET strengths = '["깊은 신념을 차분한 계획으로 옮겨 오래 가는 흐름을 만듭니다.", "크게 외치지 않아도 사람들이 스스로 따라오게 만듭니다.", "결과가 늦게 나오는 긴 프로젝트도 흔들림 없이 끌고 갑니다.", "서로 부딪히는 가치들 사이에서 함께 갈 수 있는 길을 찾습니다."]'::jsonb, cautions = '["이상과 현실의 차이가 크면 먼저 지칠 수 있어요. 작은 목표를 세워 진행되고 있다는 걸 느껴 보세요.", "힘든 마음을 혼자 삼키지 말고 믿을 수 있는 동료에게 꺼내 놓으세요.", "결과가 느려도 흔들리지 않도록 매일 지키는 작은 루틴을 만들어 두세요."]'::jsonb, fit_direction = '지금은 교육 봉사·사회 문제 프로젝트·정책 공모전처럼 의미 있는 일을 직접 기획해 보세요. 첫 직무로는 교육 기획·정책 연구·사회공헌·비영리 단체 기획이 잘 맞습니다. 길게는 사회적 가치를 실현하는 조직의 리더나 창립자로 성장할 수 있습니다.' WHERE type_code = 'D-INFJ';
UPDATE public.hit_hero_types SET strengths = '["평소엔 조용하지만 지켜야 할 가치 앞에서는 누구보다 단단해집니다.", "말로 설득하기보다 오랜 실천으로 주변을 바꿔 갑니다.", "남들이 지나치는 보이지 않는 가치를 알아보고 지킵니다.", "타협해야 할 때도 가장 중요한 것은 놓치지 않습니다."]'::jsonb, cautions = '["꼭 지켜야 할 가치와 바꿔도 되는 방법을 구분해 보세요. 방법은 유연해도 가치는 지켜집니다.", "양보가 필요한 순간에 너무 오래 망설이지 않도록, 내 기준선을 미리 정해 두세요.", "이상만 보지 않도록 현실을 잘 아는 사람의 조언을 정기적으로 들어 보세요."]'::jsonb, fit_direction = '지금은 환경·인권·윤리 같은 관심 주제로 활동하거나 글을 써서 생각을 나눠 보세요. 첫 직무로는 비영리 단체·ESG·연구·콘텐츠 기획이 잘 맞습니다. 길게는 내가 믿는 가치를 대표하는 활동가나 전문가로 성장할 수 있습니다.' WHERE type_code = 'D-INFP';
UPDATE public.hit_hero_types SET strengths = '["아무것도 없는 상태에서 혼자서도 체계를 설계해 냅니다.", "치밀하게 세운 계획을 실제 행동으로 정확히 옮깁니다.", "한 번 정한 장기 목표를 끝까지 밀고 갑니다.", "복잡한 문제 앞에서도 흔들리지 않고 집중합니다."]'::jsonb, cautions = '["사람을 계획 속 변수처럼 대하지 않도록, 함께 일하는 사람의 생각을 먼저 물어보세요.", "혼자 정리하고 끝내지 말고 진행 상황을 주변과 자주 나눠 보세요.", "감정도 결과에 영향을 주는 요소입니다. 계획을 세울 때 사람들의 반응도 함께 고려하세요."]'::jsonb, fit_direction = '지금은 연구 프로젝트·개인 프로젝트로 처음부터 끝까지 혼자 설계해 보는 경험을 쌓아 보세요. 첫 직무로는 전략기획·데이터 분석·연구 개발·기술 기획이 잘 맞습니다. 길게는 자기만의 체계로 회사나 제품을 세우는 창업가로 성장할 수 있습니다.' WHERE type_code = 'D-INTJ';
UPDATE public.hit_hero_types SET strengths = '["남들이 당연하게 여기는 것에 근본적인 질문을 던집니다.", "문제의 구조를 분석해 처음부터 다시 짜는 힘이 있습니다.", "겉만 고치지 않고 근본 원인을 바꾸는 해법을 찾습니다.", "혼자서도 깊이 파고들어 새로운 기술이나 방법을 만들어 냅니다."]'::jsonb, cautions = '["탐구가 끝없이 길어질 수 있어요. 시작할 때 언제까지 결론을 낼지 기한을 정해 두세요.", "생각을 실제 결과물로 옮겨 줄 실행 파트너와 함께 일해 보세요.", "완성되기 전에도 중간 결과를 공유하세요. 피드백이 방향을 잡아 줍니다."]'::jsonb, fit_direction = '지금은 연구실·학회·오픈소스 프로젝트에서 한 주제를 깊이 파고드는 경험을 쌓아 보세요. 첫 직무로는 연구 개발·데이터 사이언스·소프트웨어 개발·기술 기획이 잘 맞습니다. 길게는 연구 조직을 이끄는 리더나 기술 기반 창업가로 성장할 수 있습니다.' WHERE type_code = 'D-INTP';
UPDATE public.hit_hero_types SET strengths = '["요란하지 않게 맡은 자리와 사람을 끝까지 지킵니다.", "시간이 지날수록 ''이 사람이 있어 다행''이라는 신뢰가 쌓입니다.", "긴 프로젝트에서 흔들리지 않는 중심축 역할을 합니다.", "사람을 챙기면서 맡은 책임도 함께 완수합니다."]'::jsonb, cautions = '["모든 걸 혼자 짊어지다 한 번에 무너질 수 있어요. 나눌 수 있는 일은 나눠 맡기세요.", "쉬는 시간도 업무 일정만큼 중요하게 달력에 넣어 두세요.", "묵묵히 한 일은 잘 보이지 않습니다. 내가 한 일을 기록하고 필요할 때 알리세요."]'::jsonb, fit_direction = '지금은 동아리·학생회 총무나 운영진처럼 조직을 안정적으로 지키는 역할을 맡아 보세요. 첫 직무로는 운영 관리·인사·교육 행정·공공기관 실무가 잘 맞습니다. 길게는 조직과 공동체를 오래 이끄는 신뢰받는 책임자로 성장할 수 있습니다.' WHERE type_code = 'D-ISFJ';
UPDATE public.hit_hero_types SET strengths = '["내 안에서 우러나는 나만의 표현으로 작품을 만듭니다.", "자기만의 세계를 꾸준히 쌓아 가는 창작 의지가 있습니다.", "남이 정한 규칙보다 스스로 세운 기준을 따릅니다.", "한 작품에 깊이 몰입해 완성도를 끌어올립니다."]'::jsonb, cautions = '["작업에 몰입하다 협업이 어려워질 수 있어요. 일정과 소통을 맡아 줄 파트너를 일찍 찾아 두세요.", "혼자 깊이 들어갈수록 바깥과 대화하는 시간도 일부러 만들어 보세요.", "내 기준만큼 보는 사람의 반응도 중요합니다. 작업을 주기적으로 보여 주고 의견을 들어 보세요."]'::jsonb, fit_direction = '지금은 개인 작품·포트폴리오를 꾸준히 만들고 전시·업로드로 세상에 보여 주는 경험을 쌓아 보세요. 첫 직무로는 디자이너·영상 제작·콘텐츠 크리에이터·프리랜서 창작이 잘 맞습니다. 길게는 자기 이름을 건 스튜디오나 브랜드를 운영하는 창작자로 성장할 수 있습니다.' WHERE type_code = 'D-ISFP';
UPDATE public.hit_hero_types SET strengths = '["정한 원칙을 끝까지 지키며 일을 밀고 나갑니다.", "흔들리는 상황에서도 기준을 잡아 조직을 단단하게 합니다.", "맡은 범위의 일은 빈틈없이 마무리합니다.", "분위기에 휩쓸리지 않고 기준에 따라 판단합니다."]'::jsonb, cautions = '["원칙의 목적과 형식을 구분해 보세요. 목적이 지켜진다면 방식은 바꿔도 됩니다.", "예외 상황이 생기면 스트레스가 쌓일 수 있어요. 예외를 다루는 기준도 미리 정해 두세요.", "유연한 동료와 함께 일하면 서로의 빈 곳을 채울 수 있습니다."]'::jsonb, fit_direction = '지금은 자격증 준비나 규정·절차가 분명한 일을 맡아 정확하게 해내는 경험을 쌓아 보세요. 첫 직무로는 감사·법무·품질관리·공공기관·재무가 잘 맞습니다. 길게는 조직의 기준을 지키는 신뢰받는 책임자로 성장할 수 있습니다.' WHERE type_code = 'D-ISTJ';
UPDATE public.hit_hero_types SET strengths = '["결정적인 순간에 손을 움직여 해법을 찾아냅니다.", "복잡한 문제 앞에서도 침착하게 원인을 짚습니다.", "말로 설명하기보다 직접 만들어 보여 줍니다.", "혼자 맡은 작업을 깊이 있게 해냅니다."]'::jsonb, cautions = '["말수가 적어 오해를 살 수 있어요. 무엇을 왜 하는지 짧게라도 공유하세요.", "혼자 해결하는 것이 편해도 팀과 연락하는 통로는 열어 두세요.", "기술은 빠르게 바뀝니다. 새로 배울 것 하나를 꾸준히 정해 두세요."]'::jsonb, fit_direction = '지금은 만들기·수리·코딩처럼 직접 손으로 문제를 해결하는 프로젝트를 해 보세요. 첫 직무로는 엔지니어·개발자·기술 지원·설비·품질 분야가 잘 맞습니다. 길게는 어려운 문제를 맡기는 수석 엔지니어나 기술 전문가로 성장할 수 있습니다.' WHERE type_code = 'D-ISTP';
UPDATE public.hit_hero_types SET strengths = '["대화 속에서 상대가 미처 몰랐던 강점을 먼저 알아봅니다.", "상대가 다음에 무엇을 하면 좋을지 함께 그려 주는 힘이 있습니다.", "나와 이야기한 사람이 자신감을 얻어 돌아가게 만듭니다.", "깊이 있는 관계를 맺고 오래 이어 갑니다."]'::jsonb, cautions = '["남의 감정에 깊이 들어가다 보면 내 생각이 흐려질 수 있어요. 내 의견을 먼저 적어 두고 대화에 들어가 보세요.", "도움을 주는 만큼 나도 회복해야 합니다. 혼자 쉬는 시간을 일정에 먼저 넣어 두세요.", "모든 사람을 다 도울 수는 없습니다. 내가 도울 수 있는 범위를 정해 두세요."]'::jsonb, fit_direction = '지금은 멘토링·튜터링·스터디 리더처럼 다른 사람의 성장을 돕는 경험을 쌓아 보세요. 첫 직무로는 HR·교육 담당(HRD)·커리어 상담·고객 성공 매니저가 잘 맞습니다. 길게는 사람의 성장을 돕는 코치나 인재 개발 전문가로 성장할 수 있습니다.' WHERE type_code = 'I-ENFJ';
UPDATE public.hit_hero_types SET strengths = '["딱딱한 정보를 사람의 마음에 닿는 이야기로 바꿉니다.", "메시지를 전하는 데서 그치지 않고 사람들이 참여하고 싶게 만듭니다.", "새로운 아이디어가 끊임없이 떠오르고 그걸 즐겁게 풀어냅니다.", "처음 만난 사람과도 금방 공감대를 만듭니다."]'::jsonb, cautions = '["아이디어가 많아 방향이 흩어질 수 있어요. 함께 우선순위를 정해 줄 파트너를 두세요.", "하고 싶은 말을 한 줄로 줄이는 연습을 해 보세요. 메시지가 더 멀리 갑니다.", "시작한 일을 끝까지 마무리했는지 한 주에 한 번 점검해 보세요."]'::jsonb, fit_direction = '지금은 SNS 채널 운영·콘텐츠 제작·동아리 홍보처럼 이야기로 사람을 모으는 경험을 쌓아 보세요. 첫 직무로는 콘텐츠 마케팅·브랜드 마케팅·카피라이팅·커뮤니티 운영이 잘 맞습니다. 길게는 브랜드의 이야기를 만드는 크리에이티브 디렉터나 자기 브랜드의 창업가로 성장할 수 있습니다.' WHERE type_code = 'I-ENFP';
UPDATE public.hit_hero_types SET strengths = '["사람 사이의 관계를 전략의 자원으로 활용합니다.", "숫자와 사람의 마음을 함께 읽어 협상과 협력을 이끕니다.", "여러 조직을 연결해 혼자서는 못 할 일을 가능하게 만듭니다.", "큰 방향을 세우고 그걸 함께 할 사람을 찾아 모읍니다."]'::jsonb, cautions = '["아는 사람이 많아질수록 집중이 흩어질 수 있어요. 정말 중요한 관계 몇 개에 시간을 먼저 쓰세요.", "관계를 넓히는 만큼 약속을 지키는 일도 늘어납니다. 지킬 수 있는 만큼만 약속하세요.", "사람들을 전략의 일부로만 보지 않도록, 상대에게 무엇이 도움이 될지도 함께 생각해 보세요."]'::jsonb, fit_direction = '지금은 대외 협력·스폰서 유치·연합 행사 기획처럼 외부와 손잡는 경험을 쌓아 보세요. 첫 직무로는 사업개발(BD)·제휴·영업 기획·대외 협력이 잘 맞습니다. 길게는 파트너십을 총괄하는 리더나 자문가로 성장할 수 있습니다.' WHERE type_code = 'I-ENTJ';
UPDATE public.hit_hero_types SET strengths = '["질문을 던져 막혀 있던 대화를 열어 줍니다.", "반대 의견을 두려워하지 않고 오히려 즐기며 생각을 넓힙니다.", "서로 상관없어 보이는 것들을 연결해 새로운 관점을 만듭니다.", "생각을 말로 재미있게 풀어내 사람들의 관심을 끕니다."]'::jsonb, cautions = '["논쟁이 길어지면 상대가 지칠 수 있어요. 상대가 받아들일 시간을 주세요.", "결론을 강요하기보다 상대가 스스로 생각할 질문을 남겨 보세요.", "말로 끝나지 않도록 아이디어 하나는 실제 결과물로 만들어 보세요."]'::jsonb, fit_direction = '지금은 토론 대회·발표·영상이나 글 콘텐츠로 내 생각을 세상에 꺼내 보세요. 첫 직무로는 콘텐츠 기획·전략 기획·홍보(PR)·교육 강사가 잘 맞습니다. 길게는 생각을 나누는 강연가나 자기 미디어를 운영하는 크리에이터로 성장할 수 있습니다.' WHERE type_code = 'I-ENTP';
UPDATE public.hit_hero_types SET strengths = '["사람마다 다른 성향을 읽고 잘 어울리도록 연결합니다.", "모인 자리의 분위기를 편안하고 따뜻하게 만듭니다.", "작은 정성까지 챙겨 사람들이 다시 오고 싶게 만듭니다.", "누구와도 금방 친해지고 그 관계를 잘 유지합니다."]'::jsonb, cautions = '["모두를 만족시키려다 내 생각을 감출 수 있어요. 내 의견을 한 번은 분명히 말해 보세요.", "부탁을 다 들어주지 않아도 됩니다. 거절해도 좋은 관계는 유지됩니다.", "사람을 챙기느라 내 일이 밀리지 않았는지 하루 끝에 확인해 보세요."]'::jsonb, fit_direction = '지금은 동아리·행사 운영진, 신입생 환영회처럼 사람을 모으고 이어 주는 역할을 맡아 보세요. 첫 직무로는 커뮤니티 매니저·고객 성공·이벤트 운영·HR이 잘 맞습니다. 길게는 사람이 모이는 브랜드나 공간을 운영하는 리더로 성장할 수 있습니다.' WHERE type_code = 'I-ESFJ';
UPDATE public.hit_hero_types SET strengths = '["내가 있는 자리의 분위기를 순식간에 밝게 바꿉니다.", "사람들의 반응을 바로 읽고 그에 맞춰 즉석에서 대응합니다.", "현장의 열기를 참여·반응·매출 같은 결과로 바꿔 냅니다.", "새로운 상황에 빠르게 적응하고 자기 표현이 자연스럽습니다."]'::jsonb, cautions = '["반응이 없을 때 쉽게 지칠 수 있어요. 반응과 상관없이 지키는 나만의 루틴을 만들어 두세요.", "칭찬만 해 주는 사람 말고, 솔직하게 피드백해 줄 사람을 곁에 두세요.", "바쁜 시기가 끝나면 쉬는 날을 미리 정해 두세요. 에너지는 쓰는 만큼 채워야 합니다."]'::jsonb, fit_direction = '지금은 행사 진행·발표·영상 콘텐츠 제작으로 무대 경험을 쌓아 보세요. 첫 직무로는 브랜드 마케팅·이벤트·영업·크리에이터가 잘 맞습니다. 길게는 내 이름이 브랜드가 되는 엔터테인먼트·라이프스타일 분야로 성장할 수 있습니다.' WHERE type_code = 'I-ESFP';
UPDATE public.hit_hero_types SET strengths = '["목표 숫자를 분명히 세우고 팀이 그걸 향해 움직이게 만듭니다.", "팀을 밀어붙이면서도 사람과의 관계를 놓치지 않습니다.", "성과를 내는 동시에 팀을 하나로 묶습니다.", "할 일을 체계적으로 나눠 실행을 빠르게 만듭니다."]'::jsonb, cautions = '["당장의 숫자에 집중하다 새로운 시도를 놓칠 수 있어요. 분기마다 방향이 맞는지 점검해 보세요.", "익숙한 방식만 쓰지 않도록 다른 분야 사람의 의견을 일부러 들어 보세요.", "목표를 강조할 때 팀원 각자의 사정도 한 번 물어보세요."]'::jsonb, fit_direction = '지금은 판매 아르바이트·후원 모금·동아리 운영처럼 목표를 세우고 팀과 달성하는 경험을 쌓아 보세요. 첫 직무로는 영업·영업 관리·매장 운영·유통이 잘 맞습니다. 길게는 영업 조직을 이끄는 리더나 유통 사업가로 성장할 수 있습니다.' WHERE type_code = 'I-ESTJ';
UPDATE public.hit_hero_types SET strengths = '["말로 신뢰를 쌓아 현장에서 결정을 이끌어 냅니다.", "상대가 마음을 정하는 순간을 정확히 읽어 냅니다.", "준비한 것보다 상황에 맞춰 대응하는 순발력이 뛰어납니다.", "결과가 바로 보이는 환경에서 실력이 빛납니다."]'::jsonb, cautions = '["준비 없이 계속 뛰어들면 금방 지칩니다. 만난 사람과 약속을 기록하는 습관을 들이세요.", "한 번의 성사보다 오래 가는 관계가 더 큰 결과를 냅니다. 연락을 이어 가는 체계를 만들어 두세요.", "속도만큼 꼼꼼함이 필요한 일은 함께 챙겨 줄 동료와 나눠 보세요."]'::jsonb, fit_direction = '지금은 판매·중고 거래·후원 유치처럼 직접 사람을 설득해 결과를 내는 경험을 쌓아 보세요. 첫 직무로는 영업·기업 영업(B2B)·부동산·중개 분야가 잘 맞습니다. 길게는 영업을 총괄하는 리더나 자기 사업을 하는 사업가로 성장할 수 있습니다.' WHERE type_code = 'I-ESTP';
UPDATE public.hit_hero_types SET strengths = '["한 사람의 이야기를 깊이 들어 마음속 생각을 꺼내도록 돕습니다.", "대화가 끝나면 상대가 자기 마음을 더 잘 이해하게 됩니다.", "말을 많이 하지 않아도 곁에 있는 것만으로 힘이 됩니다.", "겉으로 드러나지 않은 감정과 의미를 읽어 냅니다."]'::jsonb, cautions = '["남의 아픔을 내 것처럼 떠안다 무거워질 수 있어요. 내 이야기를 들어 줄 사람을 한 명 정해 두세요.", "깊은 대화를 나눈 날에는 혼자 회복하는 시간을 꼭 가지세요.", "도움이 더 필요한 사람에게는 전문가를 연결해 주는 것도 좋은 도움입니다."]'::jsonb, fit_direction = '지금은 또래 상담·멘토링·봉사 활동으로 한 사람의 이야기를 깊이 들어 보는 경험을 쌓아 보세요. 첫 직무로는 상담·코칭·교육·사회복지 분야가 잘 맞습니다. 길게는 사람의 마음을 돕는 전문 상담가나 코치로 성장할 수 있습니다.' WHERE type_code = 'I-INFJ';
UPDATE public.hit_hero_types SET strengths = '["말로 꺼내기 어려운 감정을 글로 대신 표현해 줍니다.", "공감의 깊이가 문장에 담겨 읽는 사람의 마음을 움직입니다.", "브랜드나 사람의 목소리를 섬세하게 찾아냅니다.", "자기만의 시선으로 평범한 것에서 의미를 발견합니다."]'::jsonb, cautions = '["완벽하게 쓰려다 마감을 놓칠 수 있어요. 초안 마감과 완성 마감을 따로 정해 두세요.", "혼자 고치기만 하지 말고 초안을 일찍 보여 주고 의견을 받아 보세요.", "감정에 깊이 빠지는 날에는 글보다 휴식을 먼저 챙기세요."]'::jsonb, fit_direction = '지금은 블로그·에세이·학보사·SNS 글쓰기로 꾸준히 글을 쓰고 공개해 보세요. 첫 직무로는 카피라이터·콘텐츠 에디터·브랜드 커뮤니케이션·출판 편집이 잘 맞습니다. 길게는 브랜드의 목소리를 책임지는 디렉터나 작가로 성장할 수 있습니다.' WHERE type_code = 'I-INFP';
UPDATE public.hit_hero_types SET strengths = '["사람들의 말 뒤에 숨은 생각의 구조를 읽어 냅니다.", "데이터 속에서 사람의 행동과 이유를 찾아냅니다.", "흩어진 정보를 모아 분명한 통찰로 정리합니다.", "관계 속에서 관찰한 것을 전략으로 바꿉니다."]'::jsonb, cautions = '["분석만 쌓이고 실행이 늦어질 수 있어요. 분석할 때마다 제안 하나를 꼭 붙여 보세요.", "완벽한 결론을 기다리기보다 중간 결과를 먼저 공유해 보세요.", "실행을 잘하는 동료와 짝을 이루면 통찰이 결과가 됩니다."]'::jsonb, fit_direction = '지금은 설문·인터뷰 조사, 리서치 프로젝트로 사람의 생각을 분석해 보는 경험을 쌓아 보세요. 첫 직무로는 고객 리서치(UX 리서치)·전략 분석·마케팅 인사이트·컨설팅이 잘 맞습니다. 길게는 통찰로 방향을 제시하는 전략 컨설턴트나 리서치 전문가로 성장할 수 있습니다.' WHERE type_code = 'I-INTJ';
UPDATE public.hit_hero_types SET strengths = '["궁금한 것을 끝까지 파고들어 깊이 있게 이해합니다.", "어려운 내용을 내 언어로 쉽게 풀어냅니다.", "전문 지식과 대중 사이의 다리가 되어 줍니다.", "다양한 분야에 대한 호기심이 새로운 주제를 계속 만들어 냅니다."]'::jsonb, cautions = '["관심사가 많아 한 주제에 오래 머물기 어려울 수 있어요. 주제를 시리즈로 묶어 이어 가 보세요.", "자료 조사가 끝없이 길어지지 않도록 공개할 날짜를 먼저 정하세요.", "만든 콘텐츠에 대한 반응을 보고 다음 주제를 고르는 습관을 들여 보세요."]'::jsonb, fit_direction = '지금은 공부한 내용을 블로그·영상·스터디 발표로 정리해 다른 사람에게 설명해 보세요. 첫 직무로는 교육 콘텐츠 기획·테크니컬 라이터·리서치·강사가 잘 맞습니다. 길게는 지식을 전하는 교육 크리에이터나 교육 사업가로 성장할 수 있습니다.' WHERE type_code = 'I-INTP';
UPDATE public.hit_hero_types SET strengths = '["팀의 분위기를 조용히 따뜻하게 만듭니다.", "사람들이 부탁한 것을 기억하고 말없이 해결해 줍니다.", "화려하지 않지만 없으면 빈자리가 크게 느껴지는 사람입니다.", "세심하게 챙겨 팀이 안정적으로 굴러가게 합니다."]'::jsonb, cautions = '["묵묵히 한 일은 잘 보이지 않아 저평가될 수 있어요. 내가 한 일을 정리해 정기적으로 알리세요.", "내 경력을 남이 정해 주길 기다리지 말고 가고 싶은 방향을 직접 그려 보세요.", "도와 달라는 말을 하는 것도 연습해 보세요. 받는 것도 관계입니다."]'::jsonb, fit_direction = '지금은 동아리 총무·행사 지원·학생 조교처럼 팀을 뒤에서 받치는 역할을 맡아 보세요. 첫 직무로는 HR·경영 지원·운영 지원·고객 지원이 잘 맞습니다. 길게는 조직이 믿고 맡기는 핵심 운영 담당자나 팀 매니저로 성장할 수 있습니다.' WHERE type_code = 'I-ISFJ';
UPDATE public.hit_hero_types SET strengths = '["말로 설명하기 어려운 분위기와 결을 감각으로 잡아냅니다.", "자기만의 색깔로 공간이나 화면을 채웁니다.", "작은 디테일까지 신경 써 결과물의 완성도가 다릅니다.", "사람들이 느낄 감정을 먼저 생각하며 디자인합니다."]'::jsonb, cautions = '["감으로 만든 결과를 설명하기 어려울 수 있어요. 디자인 의도를 세 문장으로 정리하는 연습을 해 보세요.", "시안을 혼자 오래 붙잡지 말고 일찍 보여 주고 의견을 받아 보세요.", "내 취향과 사용자의 필요가 다를 때는 사용자의 필요를 먼저 확인하세요."]'::jsonb, fit_direction = '지금은 개인 작업·공모전·SNS 포트폴리오로 내 감각을 보여 주는 결과물을 꾸준히 쌓아 보세요. 첫 직무로는 UX/UI 디자이너·그래픽 디자이너·공간 디자인·브랜드 디자인이 잘 맞습니다. 길게는 브랜드의 감각을 책임지는 디렉터나 자기 스튜디오를 운영하는 디자이너로 성장할 수 있습니다.' WHERE type_code = 'I-ISFP';
UPDATE public.hit_hero_types SET strengths = '["무슨 일이 있었는지, 누가 무엇을 했는지 정확히 기록합니다.", "조직의 경험을 잊히지 않게 남기는 ''기억'' 역할을 합니다.", "사실을 꼼꼼히 확인하고 왜곡 없이 전달합니다.", "흩어진 정보를 찾아 정리하는 끈기가 있습니다."]'::jsonb, cautions = '["사실과 내 해석이 섞이지 않도록 둘을 구분해서 쓰는 습관을 들이세요.", "기록이 쌓이기만 하지 않도록, 사람들이 쉽게 찾아볼 수 있게 정리해 두세요.", "정확성을 지키되 공유할 타이밍을 놓치지 않도록 마감을 정해 두세요."]'::jsonb, fit_direction = '지금은 학보사·동아리 기록 담당·회의록 작성처럼 사실을 정확히 정리하는 경험을 쌓아 보세요. 첫 직무로는 사내 커뮤니케이션·기자·기록 관리·홍보 콘텐츠 작성이 잘 맞습니다. 길게는 조직의 기록과 소통을 책임지는 편집 리더나 전문 기자로 성장할 수 있습니다.' WHERE type_code = 'I-ISTJ';
UPDATE public.hit_hero_types SET strengths = '["복잡한 것을 직접 만들어 보여 주며 쉽게 이해시킵니다.", "말보다 시제품으로 설명하는 실용적인 감각이 있습니다.", "사람들과 함께 손을 움직이며 배우는 자리를 잘 이끕니다.", "실제로 작동하는지 확인하며 문제를 해결합니다."]'::jsonb, cautions = '["그때그때 대응하다 보면 전체 그림이 흐려질 수 있어요. 시작할 때 큰 구조를 한 번 잡아 두세요.", "만드는 과정을 기록해 두면 다른 사람도 따라 할 수 있습니다.", "혼자 해결하는 게 편해도 진행 상황은 주변과 짧게라도 나누세요."]'::jsonb, fit_direction = '지금은 메이커 동아리·만들기 워크숍·DIY 콘텐츠로 손으로 만드는 경험을 쌓아 보세요. 첫 직무로는 제품 개발·기술 교육·하드웨어 엔지니어·공방 운영이 잘 맞습니다. 길게는 만드는 법을 가르치는 교육자나 자기 메이커 브랜드의 운영자로 성장할 수 있습니다.' WHERE type_code = 'I-ISTP';
UPDATE public.hit_hero_types SET strengths = '["한 사람의 성장을 오래 지켜보며 곁을 지킵니다.", "빠른 변화보다 꾸준히 쌓이는 변화를 만들어 냅니다.", "따뜻한 피드백으로 상대가 스스로 다음 걸음을 내딛게 합니다.", "시간이 지날수록 ''이 사람 덕분에 컸다''는 말을 듣습니다."]'::jsonb, cautions = '["관계가 길어질수록 객관적으로 보기 어려워질 수 있어요. 다른 사람의 시선으로 한 번씩 점검받아 보세요.", "상대의 성장을 기다리다 내 성장을 미루지 않도록, 나를 위한 배움 목표도 세워 두세요.", "모든 사람을 오래 돌볼 수는 없습니다. 지금 집중할 사람을 정해 두세요."]'::jsonb, fit_direction = '지금은 튜터링·멘토링·스터디 운영처럼 다른 사람을 꾸준히 이끌어 주는 경험을 쌓아 보세요. 첫 직무로는 교육 담당(HRD)·교육 기획·커리어 상담·고객 성공 매니저가 잘 맞습니다. 길게는 사람을 키우는 코치나 학습 공동체의 리더로 성장할 수 있습니다.' WHERE type_code = 'S-ENFJ';
UPDATE public.hit_hero_types SET strengths = '["사람의 이야기를 잘 들어 주어 상대가 마음을 열게 만듭니다.", "관계 안에서 에너지를 얻고 그 에너지를 다시 나눕니다.", "사람이 가진 가능성을 찾아 피어나도록 응원합니다.", "편안하고 따뜻한 분위기로 사람들을 모읍니다."]'::jsonb, cautions = '["모두에게 좋은 사람이 되려다 내 일이 밀릴 수 있어요. 일주일에 한 번 내 우선순위를 점검하세요.", "부탁을 다 들어주지 않아도 괜찮습니다. 거절해도 관계는 이어집니다.", "하고 싶은 일이 많을 때는 이번 달에 끝낼 한 가지를 먼저 고르세요."]'::jsonb, fit_direction = '지금은 동아리·봉사·커뮤니티 활동에서 사람을 모으고 함께하는 프로그램을 운영해 보세요. 첫 직무로는 커뮤니티 매니저·교육 프로그램 기획·HR·고객 경험(CX)이 잘 맞습니다. 길게는 사람이 성장하는 프로그램을 만드는 디렉터나 코치로 성장할 수 있습니다.' WHERE type_code = 'S-ENFP';
UPDATE public.hit_hero_types SET strengths = '["무리하게 확장하기보다 체계적으로 쌓아 조직을 키웁니다.", "안정과 성장을 함께 잡는 균형 감각이 있습니다.", "긴 시간이 걸리는 프로젝트도 흔들림 없이 이끕니다.", "시간이 지날수록 조직을 단단하고 두껍게 만듭니다."]'::jsonb, cautions = '["안정을 중시하다 변화의 신호를 놓칠 수 있어요. 바깥 동향을 정기적으로 살펴보세요.", "익숙한 판단 기준만 쓰지 않도록 외부의 조언을 일부러 들어 보세요.", "계획을 지키는 것만큼, 계획을 바꿔야 할 때를 알아채는 것도 중요합니다."]'::jsonb, fit_direction = '지금은 학생회·동아리에서 1년 이상 이어지는 운영을 맡아 조직을 꾸준히 키워 보세요. 첫 직무로는 경영기획·사업관리·운영 관리·재무 기획이 잘 맞습니다. 길게는 조직을 안정적으로 성장시키는 경영자로 성장할 수 있습니다.' WHERE type_code = 'S-ENTJ';
UPDATE public.hit_hero_types SET strengths = '["있던 것을 허물지 않고 그 위에 새로운 방향을 얹습니다.", "전통과 새로움 사이에서 양쪽을 연결하는 다리가 됩니다.", "여러 사람의 입장을 고려해 받아들여질 만한 변화를 설계합니다.", "기존 자원을 새롭게 활용할 방법을 찾아냅니다."]'::jsonb, cautions = '["양쪽을 다 고려하다 결정이 늦어질 수 있어요. 결정할 날짜를 미리 정하고 지키세요.", "모두를 만족시키는 답은 없을 수 있습니다. 가장 중요한 기준 하나를 먼저 정하세요.", "아이디어를 내는 데서 멈추지 말고 작게라도 실제로 시험해 보세요."]'::jsonb, fit_direction = '지금은 기존 행사나 서비스를 새롭게 바꿔 보는 개선 프로젝트를 맡아 보세요. 첫 직무로는 서비스 기획·제품 관리(PM)·신사업 기획·브랜드 전략이 잘 맞습니다. 길게는 조직의 변화를 설계하는 혁신 리더로 성장할 수 있습니다.' WHERE type_code = 'S-ENTP';
UPDATE public.hit_hero_types SET strengths = '["누가 무엇을 필요로 하는지 말하기 전에 먼저 알아챕니다.", "고객과 팀원 모두가 존중받는다고 느끼게 만드는 서비스 감각이 있습니다.", "팀의 분위기와 고객의 기분 변화를 빠르게 감지합니다.", "놓치기 쉬운 작은 일까지 챙겨 일이 매끄럽게 굴러가게 합니다."]'::jsonb, cautions = '["모든 일을 혼자 챙기려다 지칠 수 있어요. 체크리스트를 만들어 나눠 맡겨 보세요.", "부탁을 다 들어주지 않아도 괜찮습니다. 거절해도 관계는 무너지지 않아요.", "남을 챙기는 만큼 나를 챙기는 시간도 일정에 넣어 두세요."]'::jsonb, fit_direction = '지금은 동아리 운영진·행사 운영·서비스 아르바이트로 사람을 챙기는 경험을 쌓아 보세요. 첫 직무로는 서비스 운영·고객 지원·HR·행정이 잘 맞습니다. 길게는 팀과 고객을 함께 책임지는 운영 리더로 성장할 수 있습니다.' WHERE type_code = 'S-ESFJ';
UPDATE public.hit_hero_types SET strengths = '["갈등이 생기면 유머로 긴장을 풀어 줍니다.", "함께 있는 공간을 편안하게 만드는 사람입니다.", "사람들을 직접 만나는 현장에서 실력이 빛납니다.", "팀의 분위기를 부드럽게 유지해 모두가 일하기 좋게 만듭니다."]'::jsonb, cautions = '["갈등을 웃음으로 덮기만 하면 문제가 쌓일 수 있어요. 꼭 짚어야 할 문제는 분명히 말해 보세요.", "분위기를 맞추느라 내 의견을 미루지 않았는지 한 번씩 돌아보세요.", "즐거운 일만큼 꾸준히 해야 하는 일도 일정에 넣어 챙기세요."]'::jsonb, fit_direction = '지금은 카페·매장·행사 스태프처럼 사람을 직접 응대하는 경험을 쌓아 보세요. 첫 직무로는 서비스 매니저·호텔·리테일·현장 운영이 잘 맞습니다. 길게는 매장이나 공간을 총괄하는 리더, 자기 서비스 브랜드의 운영자로 성장할 수 있습니다.' WHERE type_code = 'S-ESFP';
UPDATE public.hit_hero_types SET strengths = '["혼란이 와도 일이 끊기지 않고 돌아가게 만듭니다.", "숫자와 규칙, 사람을 함께 보며 운영을 관리합니다.", "정해진 절차를 지켜 안정적인 결과를 냅니다.", "책임 범위를 분명히 하고 끝까지 지킵니다."]'::jsonb, cautions = '["변화가 길어지면 답답함이 커질 수 있어요. 변화 기간과 단계별 목표를 미리 정해 두세요.", "익숙한 방식이 최선인지 가끔 다른 방식과 비교해 보세요.", "규칙을 지키는 만큼 팀원의 의견을 듣는 시간도 만들어 보세요."]'::jsonb, fit_direction = '지금은 행사·동아리의 물품·예산·일정 관리를 맡아 운영 경험을 쌓아 보세요. 첫 직무로는 생산 관리·물류·매장 운영·구매 관리가 잘 맞습니다. 길게는 조직의 운영을 책임지는 본부장이나 운영 임원으로 성장할 수 있습니다.' WHERE type_code = 'S-ESTJ';
UPDATE public.hit_hero_types SET strengths = '["요란하지 않지만 필요할 때 가장 먼저 현장에 도착합니다.", "현장에서 쌓은 관계를 실제 성과로 이어 갑니다.", "몸으로 익힌 실전 감각으로 문제를 빠르게 해결합니다.", "꾸준히 자리를 지켜 믿고 부를 수 있는 사람이 됩니다."]'::jsonb, cautions = '["반복되는 일에 익숙해지면 새로운 배움을 놓칠 수 있어요. 분기마다 배울 것 하나를 정해 두세요.", "현장 경험을 기록으로 남겨 두면 나중에 큰 자산이 됩니다.", "눈앞의 일만큼 앞으로의 방향도 한 달에 한 번 점검해 보세요."]'::jsonb, fit_direction = '지금은 현장 아르바이트·판매·행사 운영처럼 직접 몸으로 부딪히는 경험을 쌓아 보세요. 첫 직무로는 영업·기술 영업·현장 관리·서비스 엔지니어가 잘 맞습니다. 길게는 지역이나 현장을 총괄하는 리더나 지역 기반 사업가로 성장할 수 있습니다.' WHERE type_code = 'S-ESTP';
UPDATE public.hit_hero_types SET strengths = '["말을 많이 하지 않아도 곁에 있는 것만으로 상대를 안정시킵니다.", "상대를 몰아세우지 않고 생각과 감정을 차분히 꺼내 놓게 돕습니다.", "한 번 맺은 관계를 오래 이어 가며 깊은 신뢰를 쌓습니다.", "다른 사람의 어려움에 끝까지 마음을 쓰는 지속력이 있습니다."]'::jsonb, cautions = '["남의 감정을 받아 주다 보면 내가 지칠 수 있어요. 내 이야기를 들어 줄 사람을 한 명 정해 두세요.", "회복 시간은 남는 시간이 아니라 일정입니다. 혼자 쉬는 시간을 달력에 먼저 넣어 두세요.", "상대의 문제를 내 문제처럼 떠안지 않도록, 도울 수 있는 범위를 미리 정해 두세요."]'::jsonb, fit_direction = '지금은 또래 상담·멘토링·봉사 활동으로 사람을 돕는 경험을 쌓아 보세요. 첫 직무로는 상담·교육·HR·고객 경험(CX)처럼 사람의 마음을 다루는 일이 잘 맞습니다. 길게는 코치·상담가·커뮤니티 리더로 성장할 수 있습니다.' WHERE type_code = 'S-INFJ';
UPDATE public.hit_hero_types SET strengths = '["사라질 수 있는 소중한 것을 알아보고 오래 지킵니다.", "꾸준하고 섬세하게 기록하고 정리합니다.", "자료와 이야기에 담긴 의미를 깊이 이해합니다.", "조용한 환경에서 오래 집중해 완성도를 높입니다."]'::jsonb, cautions = '["지키는 데 집중하다 변화에 늦을 수 있어요. 새로운 도구나 방식 하나를 꾸준히 익혀 보세요.", "보관만 하지 말고 사람들이 볼 수 있게 공유하는 방법도 함께 고민해 보세요.", "완벽하게 정리하려다 시간이 길어지지 않도록 단계별 마감을 정해 두세요."]'::jsonb, fit_direction = '지금은 학과 자료 정리·도서관 근로·기록 프로젝트처럼 정보를 모으고 보존하는 경험을 쌓아 보세요. 첫 직무로는 사서·큐레이터·기록 관리·콘텐츠 아카이빙이 잘 맞습니다. 길게는 문화와 기록을 지키는 기관의 전문가나 책임자로 성장할 수 있습니다.' WHERE type_code = 'S-INFP';
UPDATE public.hit_hero_types SET strengths = '["유행에 흔들리지 않고 한 분야의 근본을 깊이 파고듭니다.", "긴 시간 동안 지식을 쌓아 전문성을 단단하게 만듭니다.", "복잡한 주제도 체계적으로 정리해 이해합니다.", "시간이 지날수록 ''그 분야라면 이 사람''이라는 신뢰를 얻습니다."]'::jsonb, cautions = '["깊이 들어갈수록 바깥 변화에 둔해질 수 있어요. 학회나 모임에 꾸준히 나가 보세요.", "혼자 아는 데서 그치지 않도록 공부한 것을 글이나 발표로 나눠 보세요.", "완벽한 이해를 기다리기보다 중간 결과로도 의견을 들어 보세요."]'::jsonb, fit_direction = '지금은 관심 분야의 연구 프로젝트·학부 연구생·논문 읽기 모임으로 깊이를 쌓아 보세요. 첫 직무로는 연구원·전문 분석가·기술 전문직이 잘 맞습니다. 길게는 그 분야를 대표하는 연구자나 전문가로 성장할 수 있습니다.' WHERE type_code = 'S-INTJ';
UPDATE public.hit_hero_types SET strengths = '["빠른 결론보다 충분한 증거를 쌓아 판단합니다.", "숫자 뒤에 숨은 논리를 꼼꼼히 읽어 냅니다.", "꾸준한 분석으로 남들이 놓친 패턴을 찾아냅니다.", "검증된 결과만 내놓아 분석의 신뢰도가 높습니다."]'::jsonb, cautions = '["분석을 완벽하게 하려다 발표가 늦어지면 영향력을 잃을 수 있어요. 분석과 발표를 한 세트로 계획하세요.", "결과를 어려운 말 대신 한 장의 요약으로 정리하는 연습을 해 보세요.", "혼자 검토하기보다 동료에게 중간 결과를 보여 주고 의견을 받아 보세요."]'::jsonb, fit_direction = '지금은 데이터 분석 공모전·통계 프로젝트·연구 보조로 분석 경험을 쌓아 보세요. 첫 직무로는 데이터 분석가·경제·시장 분석·리서치가 잘 맞습니다. 길게는 분석 조직을 이끄는 리서치 디렉터나 전문 컨설턴트로 성장할 수 있습니다.' WHERE type_code = 'S-INTP';
UPDATE public.hit_hero_types SET strengths = '["맡은 자리에서 묵묵히 최선을 다해 주변을 안심시킵니다.", "한 사람 한 사람을 세심하게 돌봅니다.", "약속한 것을 꾸준히 지켜 신뢰를 쌓습니다.", "사람들이 편안하게 기댈 수 있는 사람입니다."]'::jsonb, cautions = '["남을 돌보느라 나를 돌보는 일이 맨 뒤로 밀리기 쉬워요. 쉬는 시간을 업무만큼 중요하게 지키세요.", "힘들 때 힘들다고 말하는 것도 연습이 필요합니다. 믿을 수 있는 사람에게 털어놓아 보세요.", "내가 한 일을 기록해 두면 나중에 경력을 설명할 때 큰 힘이 됩니다."]'::jsonb, fit_direction = '지금은 교육 봉사·돌봄 봉사·조교처럼 사람을 직접 돌보는 경험을 쌓아 보세요. 첫 직무로는 간호·교육·사회복지·고객 케어가 잘 맞습니다. 길게는 돌봄·교육 분야의 전문가나 기관 책임자로 성장할 수 있습니다.' WHERE type_code = 'S-ISFJ';
UPDATE public.hit_hero_types SET strengths = '["말보다 결과물로 실력을 보여 줍니다.", "손끝의 감각으로 섬세하게 완성도를 높입니다.", "자기 속도로 꾸준히 기술을 연마합니다.", "결과물마다 나만의 결이 담겨 있습니다."]'::jsonb, cautions = '["만드는 데 집중하다 알리는 일을 놓칠 수 있어요. 작업 과정을 SNS나 포트폴리오로 꾸준히 보여 주세요.", "판매·홍보처럼 어려운 부분은 도와줄 파트너와 나눠 보세요.", "작업 기록과 가격 기준을 정리해 두면 일이 커져도 흔들리지 않습니다."]'::jsonb, fit_direction = '지금은 공방 체험·요리·수작업 동아리로 손으로 완성하는 경험을 꾸준히 쌓아 보세요. 첫 직무로는 공예·조리·제품 제작·디자인 제작 분야가 잘 맞습니다. 길게는 자기 이름을 건 공방이나 브랜드를 운영하는 장인으로 성장할 수 있습니다.' WHERE type_code = 'S-ISFP';
UPDATE public.hit_hero_types SET strengths = '["맡긴 일은 반드시 정확하게 돌아옵니다.", "규칙과 절차를 꼼꼼히 지켜 실수가 적습니다.", "화려하지 않아도 언제나 그 자리에 있는 믿음직한 사람입니다.", "시간이 지날수록 신뢰가 두터워집니다."]'::jsonb, cautions = '["새로운 방식에 대해 처음부터 의심하기보다 작게 시험해 보고 판단해 보세요.", "정확성을 지키되 공유할 시점을 놓치지 않도록 마감을 정해 두세요.", "익숙한 일만 하지 않도록 1년에 한두 가지 새로운 업무에 도전해 보세요."]'::jsonb, fit_direction = '지금은 회계·전산 자격증 준비나 장부·예산 관리를 맡아 정확성을 쌓아 보세요. 첫 직무로는 회계·세무·공공기관 행정·총무가 잘 맞습니다. 길게는 믿고 맡기는 회계·감사 전문가나 자문가로 성장할 수 있습니다.' WHERE type_code = 'S-ISTJ';
UPDATE public.hit_hero_types SET strengths = '["문제가 생겨도 당황하지 않고 하나씩 처리합니다.", "손으로 익힌 기술을 꾸준히 갈고닦습니다.", "기계나 장비의 원리를 이해하고 정확하게 다룹니다.", "경력이 쌓일수록 전문성이 깊어집니다."]'::jsonb, cautions = '["익숙한 방식에 머물다 새 기술을 놓칠 수 있어요. 기술 모임이나 세미나에 꾸준히 참여해 보세요.", "혼자 해결한 방법을 기록해 두면 팀 전체의 자산이 됩니다.", "말수가 적어 오해를 살 수 있으니 진행 상황은 짧게라도 공유하세요."]'::jsonb, fit_direction = '지금은 실습·현장 실습·기술 자격증으로 손으로 익히는 기술을 쌓아 보세요. 첫 직무로는 설비 엔지니어·정비·생산 기술·품질 관리가 잘 맞습니다. 길게는 현장에서 가장 믿고 맡기는 마스터 엔지니어로 성장할 수 있습니다.' WHERE type_code = 'S-ISTP';
